#include <psx/display/timing.hpp>
#include <psx/display/dpf_protocol.hpp>
#include <sddl.h>
#include <fstream>
#include <iomanip>
namespace psx::du::transport {
namespace {
struct Header{uint32_t magic=0x31545044;uint16_t version=1,kind{};uint32_t bytes{},sequence{};};
struct Handle{HANDLE h{INVALID_HANDLE_VALUE};~Handle(){if(h&&h!=INVALID_HANDLE_VALUE)CloseHandle(h);}operator HANDLE()const{return h;}};
uint64_t creation(uint32_t pid){Handle p{OpenProcess(PROCESS_QUERY_LIMITED_INFORMATION,FALSE,pid)};FILETIME c{},e{},k{},u{};if(p.h==INVALID_HANDLE_VALUE||!GetProcessTimes(p,&c,&e,&k,&u))return 0;return uint64_t(c.dwLowDateTime)|(uint64_t(c.dwHighDateTime)<<32);}
std::wstring user_sid(){Handle token;std::array<uint8_t,65536>b{};DWORD n{};LPWSTR sid{};if(!OpenProcessToken(GetCurrentProcess(),TOKEN_QUERY,&token.h)||!GetTokenInformation(token,TokenUser,b.data(),DWORD(b.size()),&n)||!ConvertSidToStringSidW(reinterpret_cast<TOKEN_USER*>(b.data())->User.Sid,&sid))throw std::runtime_error("DPT user identity");std::wstring result=sid;LocalFree(sid);return result;}
struct IoStats{uint64_t read_failed{},write_failed{},timed_out{},peer_lost{},protocol_rejected{};};
bool io_failure(IoStats*stats,bool write,bool timeout){if(stats){++(write?stats->write_failed:stats->read_failed);if(timeout)++stats->timed_out;}return false;}
bool io(HANDLE pipe,bool write,void*data,DWORD size,const std::atomic<bool>&quit,IoStats*stats=nullptr){DWORD at{};while(at<size&&!quit){OVERLAPPED ov{};Handle event{CreateEventW(nullptr,TRUE,FALSE,nullptr)};if(!event.h)return io_failure(stats,write,false);ov.hEvent=event;DWORD done{};BOOL ok=write?WriteFile(pipe,static_cast<uint8_t*>(data)+at,size-at,&done,&ov):ReadFile(pipe,static_cast<uint8_t*>(data)+at,size-at,&done,&ov);if(!ok){if(GetLastError()!=ERROR_IO_PENDING)return io_failure(stats,write,false);auto due=qpc()+frequency()/4;DWORD waited=WAIT_TIMEOUT;while(!quit&&qpc()<due&&(waited=WaitForSingleObject(event,10))==WAIT_TIMEOUT){}if(quit||qpc()>=due||waited!=WAIT_OBJECT_0){CancelIoEx(pipe,&ov);GetOverlappedResult(pipe,&ov,&done,TRUE);return quit?false:io_failure(stats,write,waited==WAIT_TIMEOUT);}if(!GetOverlappedResult(pipe,&ov,&done,FALSE))return io_failure(stats,write,false);}if(!done)return io_failure(stats,write,false);at+=done;}return at==size;}
bool control(HANDLE pipe,unsigned command,unsigned&seq,const std::atomic<bool>&quit,IoStats*stats=nullptr){Header h;h.kind=2;h.bytes=8;h.sequence=++seq;std::array<unsigned,2>b{command,1};return io(pipe,true,&h,16,quit,stats)&&io(pipe,true,b.data(),8,quit,stats);}
}
struct TimingCapture::Impl {
 std::atomic<bool>quit{},failed{};std::thread worker;std::filesystem::path output;uint32_t pid;uint64_t born;
 Impl(std::filesystem::path p,uint32_t id,uint64_t c):output(std::move(p)),pid(id),born(c){std::filesystem::create_directories(output);worker=std::thread(&Impl::run,this);}
 ~Impl(){quit=true;worker.join();}
 void run(){try{std::ofstream records(output/L"source-stages.jsonl"),snapshots(output/L"source-counters.jsonl");uint64_t count{},missing{},connections{};IoStats stats;const auto started=qpc();auto name=L"\\\\.\\pipe\\psx-ios.du-timing.v1."+user_sid()+L"."+std::to_wstring(pid)+L"."+std::to_wstring(born);
 while(!quit){if(creation(pid)!=born){failed=true;break;}Handle pipe{CreateFileW(name.c_str(),GENERIC_READ|GENERIC_WRITE,0,nullptr,OPEN_EXISTING,FILE_FLAG_OVERLAPPED,nullptr)};if(pipe.h==INVALID_HANDLE_VALUE){++missing;Sleep(100);continue;}ULONG server{};if(!GetNamedPipeServerProcessId(pipe,&server)||server!=pid||creation(server)!=born)throw std::runtime_error("DPT server identity");Header h{};std::array<uint8_t,65520>b{};if(!io(pipe,false,&h,16,quit,&stats)||h.magic!=0x31545044||h.version!=1||h.kind!=1||h.sequence!=1||h.bytes<50||h.bytes>4048||!io(pipe,false,b.data(),h.bytes,quit,&stats)||psx::display::word(b.data(),0)!=pid||psx::display::word(b.data(),8)!=born||psx::display::word(b.data(),24)!=80||!identity_json({reinterpret_cast<char*>(b.data()+48),h.bytes-48}))throw std::runtime_error("DPT hello");std::array<uint8_t,16> instance{};std::copy_n(b.data()+32,16,instance.data());auto source_clock=psx::display::word(b.data(),16);if(!source_clock)throw std::runtime_error("DPT clock");std::ofstream metadata(output/(L"source-hello-"+std::to_wstring(++connections)+L".json"));metadata<<"{\"pid\":"<<pid<<",\"created\":"<<born<<",\"qpc_frequency\":"<<source_clock<<",\"connected_qpc\":"<<qpc()<<",\"source\":"<<std::string(reinterpret_cast<char*>(b.data()+48),h.bytes-48)<<"}\n";
 uint32_t in=h.sequence,out{};uint64_t renew=qpc();bool healthy=control(pipe,1,out,quit,&stats);while(healthy&&!quit){if(qpc()-renew>=frequency()/2){healthy=control(pipe,2,out,quit,&stats);renew=qpc();if(!healthy)break;}DWORD available{};if(!PeekNamedPipe(pipe,nullptr,0,nullptr,&available,nullptr)){++stats.peer_lost;break;}if(!available){Sleep(2);continue;}if(!io(pipe,false,&h,16,quit,&stats))break;if(h.magic!=0x31545044||h.version!=1||h.sequence<=in||h.bytes>b.size()){++stats.protocol_rejected;break;}if(!io(pipe,false,b.data(),h.bytes,quit,&stats))break;in=h.sequence;
 if(h.kind==3){unsigned n=psx::recorder::integer(b.data(),0);if(n>818||h.bytes!=4+n*80)throw std::runtime_error("DPT batch bounds");for(unsigned i=0;i<n;++i){auto*r=b.data()+4+i*80;auto unit=psx::recorder::integer(r,64),producer=psx::recorder::integer(r,68);if(unit>=6||producer>=18||producer%6!=unit||!std::equal(instance.begin(),instance.end(),r)||psx::recorder::integer(r,72)||psx::recorder::integer(r,76))throw std::runtime_error("DPT record identity");++count;records<<"{\"instance\":\"";for(unsigned k=0;k<16;++k)records<<std::hex<<std::setw(2)<<std::setfill('0')<<unsigned(r[k]);records<<std::dec<<"\",\"pid\":"<<pid<<",\"created\":"<<born<<",\"generation\":"<<psx::display::word(r,16)<<",\"source_frame\":"<<psx::display::word(r,24)<<",\"paint\":"<<psx::display::word(r,32)<<",\"qpc\":"<<psx::display::word(r,40)<<",\"value\":"<<psx::display::word(r,48)<<",\"thread\":"<<psx::recorder::integer(r,56)<<",\"stage\":"<<psx::recorder::integer(r,60)<<",\"unit\":"<<unit<<",\"producer\":"<<producer<<"}\n";}}
 else if(h.kind==4){if(h.bytes!=1040||psx::display::word(b.data(),0)!=2||psx::display::word(b.data(),8)!=source_clock)throw std::runtime_error("DPT snapshot");if(psx::display::word(b.data(),24))failed=true;for(unsigned i=0;i<18;++i){auto*p=b.data()+32+i*56;snapshots<<"{\"qpc\":"<<qpc()<<",\"producer\":"<<i<<",\"count\":"<<psx::display::word(p,0)<<",\"lost\":"<<psx::display::word(p,8)<<",\"entered\":"<<psx::display::word(p,16)<<",\"stage\":"<<psx::recorder::integer(p,24)<<",\"thread\":"<<psx::recorder::integer(p,28)<<",\"head\":"<<psx::display::word(p,32)<<",\"tail\":"<<psx::display::word(p,40)<<",\"lease_discarded\":"<<psx::display::word(p,48)<<"}\n";}}
 else throw std::runtime_error("DPT message kind");if(!records||!snapshots)throw std::runtime_error("DPT output");}
 std::atomic<bool> releasing{false};control(pipe,3,out,releasing,&stats);
 }std::ofstream summary(output/L"source-summary.json");summary<<"{\"records\":"<<count<<",\"connections\":"<<connections<<",\"missing_endpoint_attempts\":"<<missing<<",\"started_qpc\":"<<started<<",\"qpc_frequency\":"<<frequency()<<",\"io_read_failures\":"<<stats.read_failed<<",\"io_write_failures\":"<<stats.write_failed<<",\"io_timeouts\":"<<stats.timed_out<<",\"peer_disconnects\":"<<stats.peer_lost<<",\"protocol_rejections\":"<<stats.protocol_rejected<<",\"failed\":"<<(failed?"true":"false")<<"}\n";
 }catch(...){failed=true;try{std::ofstream error(output/L"source-error.json");error<<"{\"failed\":true,\"reason\":\"collector_exception\"}\n";}catch(...){}}}
};
TimingCapture::TimingCapture(std::filesystem::path p,uint32_t pid,uint64_t created):impl_(std::make_unique<Impl>(std::move(p),pid,created)){}TimingCapture::~TimingCapture()=default;
void TimingCapture::request_stop()noexcept{impl_->quit=true;}bool TimingCapture::failed()const noexcept{return impl_->failed;}
}
